public class TaskRunnerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        java.util.List<String> log = new java.util.ArrayList<>();
        java.util.List<Runnable> tasks = new java.util.ArrayList<>();
        tasks.add(() -> log.add("first"));
        tasks.add(() -> log.add("second"));
        tasks.add(() -> log.add("third"));
        TaskRunner.runAll(tasks);
        check("runAll runs tasks in order", "[first, second, third]", log.toString());
        TaskRunner.runAll(new java.util.ArrayList<>());
        check("runAll with empty list changes nothing", "[first, second, third]", log.toString());
        java.util.List<String> out = new java.util.ArrayList<>();
        Runnable a = TaskRunner.appender(out, "a");
        Runnable b = TaskRunner.appender(out, "b");
        check("appender returns a Runnable", true, a != null && b != null);
        if (a != null && b != null) {
            check("appender does not run immediately", "[]", out.toString());
            a.run();
            b.run();
            a.run();
            check("appender runnables append in call order", "[a, b, a]", out.toString());
            TaskRunner.runAll(java.util.List.of(b, b));
            check("runAll works with appender runnables", "[a, b, a, b, b]", out.toString());
        } else {
            check("appender does not run immediately", "[]", "skipped -- appender returned null");
            check("appender runnables append in call order", "[a, b, a]", "skipped -- appender returned null");
            check("runAll works with appender runnables", "[a, b, a, b, b]", "skipped -- appender returned null");
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

