public class TaskRunner {

    public static void runAll(java.util.List<Runnable> tasks) {
        for (Runnable task : tasks) {
            task.run();
        }
    }

    public static Runnable appender(java.util.List<String> log, String msg) {
        return () -> log.add(msg);
    }
}
